-- =====================================================================================================================
-- AptRun: AWS DATABASE UPDATE  (everything after aws-db-update-2026-10-30.sql: reports archive, scheduled mock AI interviews,
--                               CSE / IT Domain Prep, Computer Science Core mock-interview questions)
--
-- Brings an EXISTING AptRun database up to date WITHOUT replacing it. It is the SQL equivalent of
--       php artisan migrate --force
--   (2026_11_16_100000 generated_reports, 2026_11_16_100100 interview schedule, 2026_11_16_100200 CSE Domain Prep)
--   + php artisan db:seed --class=MockInterviewQuestionsSeeder   (only the new Computer Science Core stacks are added)
-- and it records the 3 migrations in the `migrations` table, so a later `php artisan migrate` will not run them again.
--
-- WHAT IT DOES
--   PART 1  schema : 1 NEW table (generated_reports: the archive of every PDF report), 6 NEW columns + 1 index on `interviews`
--                    (opens_at, closes_at, audience_filter, announced_at, open_reminder_sent_at, close_reminder_sent_at)
--   PART 2  data   : CSE / IT gets Domain Prep: capability switched on, 10 subjects / 51 topics, 160 original questions
--   PART 3  data   : Mock AI Interview: "Computer Science Core" domain (6 stacks x 3 rounds), 108 spoken questions
--   PART 4  records the migrations
--   PART 5  read-only verification
--
-- SAFE TO RE-RUN: the table uses IF NOT EXISTS, columns are added only when missing, and every row is inserted only when it
-- is not there yet (by external_id / stack+round+position). It never updates or deletes existing questions (staff edits are kept).
-- NOT touched: users, colleges, plans, subscriptions, drives, results, or any other existing data.
--
-- CSE Domain Prep stays HIDDEN FROM STUDENTS until Superadmin -> Core Prep -> Coverage -> CSE is switched live (the go-live
-- guard passes as shipped: 160 published, 5 subjects with 15+). Nothing here switches it on.
--
-- TAKE A BACKUP FIRST (RDS snapshot or mysqldump), then:
--       mysql -h <host> -u <user> -p --default-character-set=utf8mb4 <database> < aws-db-update-2026-11-04.sql
--
-- AFTER the SQL, on the server (code/cache steps, not SQL):
--       php artisan route:cache && php artisan config:cache     (new routes, config/brand.php and config/mock_interviews.php)
--       the scheduler cron (* * * * * php artisan schedule:run) now also runs `interviews:remind` every 10 minutes
--       storage/app/private must be writable by the web user (PDF reports are kept in storage/app/private/reports)
--       deploy the new frontend build
-- =====================================================================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

DROP PROCEDURE IF EXISTS _aptrun_add_column;
DELIMITER $$
CREATE PROCEDURE _aptrun_add_column(IN t VARCHAR(64), IN c VARCHAR(64), IN ddl TEXT)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = t AND column_name = c) THEN
    SET @s = CONCAT('ALTER TABLE `', t, '` ADD COLUMN `', c, '` ', ddl);
    PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
  END IF;
END$$

DROP PROCEDURE IF EXISTS _aptrun_add_index$$
CREATE PROCEDURE _aptrun_add_index(IN t VARCHAR(64), IN i VARCHAR(64), IN cols TEXT)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = t AND index_name = i) THEN
    SET @s = CONCAT('ALTER TABLE `', t, '` ADD INDEX `', i, '` (', cols, ')');
    PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
  END IF;
END$$
DELIMITER ;

-- =====================================================================================================================
-- PART 1 - SCHEMA
-- =====================================================================================================================

-- 1.1  NEW  generated_reports   (2026_11_16_100000) - the archive of every PDF report (student, interview, section); the files live in storage/app/private/reports
CREATE TABLE IF NOT EXISTS generated_reports (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  public_id VARCHAR(26) NOT NULL,
  kind VARCHAR(40) NOT NULL,
  title VARCHAR(255) NOT NULL,
  filename VARCHAR(255) NOT NULL,
  college_id BIGINT UNSIGNED NULL,
  subject_user_id BIGINT UNSIGNED NULL,
  interview_id BIGINT UNSIGNED NULL,
  interview_session_id BIGINT UNSIGNED NULL,
  generated_by BIGINT UNSIGNED NULL,
  generated_by_role VARCHAR(32) NULL,
  audience VARCHAR(16) NOT NULL DEFAULT 'staff',
  disk VARCHAR(16) NOT NULL DEFAULT 'local',
  path VARCHAR(255) NOT NULL,
  size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,
  sha256 CHAR(64) NULL,
  pages SMALLINT UNSIGNED NULL,
  params JSON NULL,
  summary JSON NULL,
  downloads INT UNSIGNED NOT NULL DEFAULT 0,
  last_downloaded_at DATETIME NULL,
  created_at TIMESTAMP NULL,
  updated_at TIMESTAMP NULL,
  PRIMARY KEY (id),
  UNIQUE KEY generated_reports_public_id_unique (public_id),
  KEY generated_reports_college_id_kind_created_at_index (college_id, kind, created_at),
  KEY generated_reports_subject_user_id_created_at_index (subject_user_id, created_at),
  KEY generated_reports_interview_id_created_at_index (interview_id, created_at),
  KEY generated_reports_generated_by_index (generated_by),
  CONSTRAINT generated_reports_college_id_foreign FOREIGN KEY (college_id) REFERENCES colleges (id) ON DELETE CASCADE,
  CONSTRAINT generated_reports_subject_user_id_foreign FOREIGN KEY (subject_user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT generated_reports_interview_id_foreign FOREIGN KEY (interview_id) REFERENCES interviews (id) ON DELETE CASCADE,
  CONSTRAINT generated_reports_interview_session_id_foreign FOREIGN KEY (interview_session_id) REFERENCES interview_sessions (id) ON DELETE CASCADE,
  CONSTRAINT generated_reports_generated_by_foreign FOREIGN KEY (generated_by) REFERENCES users (id) ON DELETE SET NULL
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- 1.2  interviews: the schedule window, the audience beyond branch, and the reminder bookkeeping (2026_11_16_100100). All nullable: an interview with none of them behaves as before.
CALL _aptrun_add_column('interviews', 'opens_at', 'DATETIME NULL AFTER qualifying_score_percent');
CALL _aptrun_add_column('interviews', 'closes_at', 'DATETIME NULL AFTER opens_at');
CALL _aptrun_add_column('interviews', 'audience_filter', 'JSON NULL AFTER closes_at');
CALL _aptrun_add_column('interviews', 'announced_at', 'DATETIME NULL AFTER audience_filter');
CALL _aptrun_add_column('interviews', 'open_reminder_sent_at', 'DATETIME NULL AFTER announced_at');
CALL _aptrun_add_column('interviews', 'close_reminder_sent_at', 'DATETIME NULL AFTER open_reminder_sent_at');
CALL _aptrun_add_index('interviews', 'interviews_type_opens_index', '`interview_type`, `opens_at`');

