SELECT '01M6JJGM2BAJCEQ1D8ZSD2R507', 'CSE-DBMS-001', 'cse', (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'dbms'), (SELECT t.id FROM core_topics t WHERE t.subject_id = (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'dbms') AND LOWER(t.name) = 'er model and keys' LIMIT 1), 'mcq_single', 'A candidate key is best described as', '[{"id":"a","text":"a minimal set of attributes that uniquely identifies every tuple"},{"id":"b","text":"any set of attributes that contains the primary key"},{"id":"c","text":"an attribute that references the primary key of another relation"},{"id":"d","text":"an attribute that may hold NULL values"}]', '["a"]', NULL, NULL, NULL, 1, 0.25, 'easy', 'A candidate key is a minimal superkey: it identifies tuples uniquely and no proper subset of it does. One candidate key is chosen as the primary key.', '["GATE \\/ campus placement style","editorial-v1"]', 'Original (AptRun editorial v1)', 'both', 'published', 1, 0, NOW(), NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM core_questions x WHERE x.external_id = 'CSE-DBMS-001');
INSERT INTO core_questions (public_id, external_id, discipline_code, subject_id, topic_id, type, stem, options, correct, numeric_min, numeric_max, numeric_unit, marks, negative_marks, difficulty, explanation, tags, source, `usage`, status, version, attempts_count, published_at, created_at, updated_at)
SELECT '01M6JJGM2BAJCEQ1D8ZSD2R508', 'CSE-DBMS-002', 'cse', (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'dbms'), (SELECT t.id FROM core_topics t WHERE t.subject_id = (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'dbms') AND LOWER(t.name) = 'er model and keys' LIMIT 1), 'mcq_single', 'In a relation R(A, B, C, D) the functional dependencies are A -> B, B -> C and C -> D. How many candidate keys does R have?', '[{"id":"a","text":"2"},{"id":"b","text":"1"},{"id":"c","text":"3"},{"id":"d","text":"4"}]', '["b"]', NULL, NULL, NULL, 1, 0.25, 'medium', 'The closure of A is {A, B, C, D}, so A is a key. No other attribute determines A, so A is the only candidate key.', '["GATE \\/ campus placement style","editorial-v1"]', 'Original (AptRun editorial v1)', 'both', 'published', 1, 0, NOW(), NOW(), NOW()
