SELECT '01M6JJGM2CYWAK7Z38GQNHR6SS', 'CSE-OS-007', 'cse', (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems'), (SELECT t.id FROM core_topics t WHERE t.subject_id = (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems') AND LOWER(t.name) = 'cpu scheduling' LIMIT 1), 'mcq_single', 'Starvation of low-priority processes in priority scheduling is usually solved by', '[{"id":"a","text":"increasing the time quantum"},{"id":"b","text":"using FCFS"},{"id":"c","text":"ageing"},{"id":"d","text":"disabling pre-emption"}]', '["c"]', NULL, NULL, NULL, 1, 0.25, 'medium', 'Ageing gradually raises the priority of processes that wait for a long time.', '["GATE \\/ campus placement style","editorial-v1"]', 'Original (AptRun editorial v1)', 'both', 'published', 1, 0, NOW(), NOW(), NOW()
