SELECT '01M6JJGM2CYWAK7Z38GQNHR6SW', 'CSE-OS-010', 'cse', (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems'), (SELECT t.id FROM core_topics t WHERE t.subject_id = (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems') AND LOWER(t.name) = 'synchronisation and deadlocks' LIMIT 1), 'mcq_single', 'A semaphore S is initialised to 1. Processes P1 and P2 each execute wait(S) then signal(S) around a critical section. This provides', '[{"id":"a","text":"no protection at all"},{"id":"b","text":"mutual exclusion"},{"id":"c","text":"deadlock-free progress only"},{"id":"d","text":"a bounded number of simultaneous entries greater than one"}]', '["b"]', NULL, NULL, NULL, 1, 0.25, 'medium', 'A binary semaphore initialised to 1 lets only one process in the critical section at a time.', '["GATE \\/ campus placement style","editorial-v1"]', 'Original (AptRun editorial v1)', 'both', 'published', 1, 0, NOW(), NOW(), NOW()
