SELECT '01M6JJGM2CYWAK7Z38GQNHR6SY', 'CSE-OS-012', 'cse', (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems'), (SELECT t.id FROM core_topics t WHERE t.subject_id = (SELECT id FROM core_subjects WHERE discipline_code = 'cse' AND code = 'operating_systems') AND LOWER(t.name) = 'synchronisation and deadlocks' LIMIT 1), 'numeric', 'A system has 12 identical resources of one type shared by n processes, each needing at most 4. What is the largest n for which deadlock is impossible?', NULL, NULL, 3, 3, NULL, 1, 0, 'hard', 'Deadlock needs every process to hold 3 (max - 1) and wait for one more, using n x 3 resources. Deadlock is impossible while 12 >= 3n + 1, so n <= 3 (for n = 4, four processes holding 3 each use all 12 and none can finish).', '["GATE \\/ campus placement style","editorial-v1"]', 'Original (AptRun editorial v1)', 'both', 'published', 1, 0, NOW(), NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM core_questions x WHERE x.external_id = 'CSE-OS-012');
