SET @aptrun_admin = (SELECT id FROM users WHERE role = 'superadmin' ORDER BY id LIMIT 1);
INSERT INTO mock_interview_questions (stack_key, round_number, topic, position, text, category, duration_seconds, note, needs_review, origin, image, created_by, created_at, updated_at)
SELECT 'cs_dbms', 1, 'Keys', 1, 'What is the difference between a primary key, a candidate key and a foreign key? Give a small example.', 'technical', 150, 'A candidate key is any minimal set of attributes that uniquely identifies a row; the primary key is the one chosen candidate (unique, not null). A foreign key references the primary or a candidate key of another table to enforce referential integrity. Example: Student(roll_no PK), Enrolment(roll_no FK).', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 1);
INSERT INTO mock_interview_questions (stack_key, round_number, topic, position, text, category, duration_seconds, note, needs_review, origin, image, created_by, created_at, updated_at)
SELECT 'cs_dbms', 1, 'DBMS basics', 2, 'Explain the difference between DBMS and a file system. Why do applications use a database instead of plain files?', 'technical', 150, 'A DBMS adds data independence, reduced redundancy and inconsistency, concurrent access control, atomic transactions and recovery, security and integrity constraints, and a query language. Files leave all of that to every application.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 2);
INSERT INTO mock_interview_questions (stack_key, round_number, topic, position, text, category, duration_seconds, note, needs_review, origin, image, created_by, created_at, updated_at)
SELECT 'cs_dbms', 1, 'SQL joins', 3, 'Walk me through the main SQL join types. When would you use a LEFT JOIN rather than an INNER JOIN?', 'technical', 150, 'INNER returns only matching rows; LEFT keeps every left row with NULLs where nothing matches; RIGHT mirrors it; FULL keeps both sides; CROSS is the cartesian product. LEFT JOIN is used when rows without a match must still appear, for example all customers including those with no orders.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 3);
INSERT INTO mock_interview_questions (stack_key, round_number, topic, position, text, category, duration_seconds, note, needs_review, origin, image, created_by, created_at, updated_at)
SELECT 'cs_dbms', 1, 'SQL commands', 4, 'What is the difference between DELETE, TRUNCATE and DROP?', 'technical', 150, 'DELETE removes chosen rows (DML), can have a WHERE, fires triggers and can be rolled back. TRUNCATE removes all rows quickly, resets identity, usually minimal logging and cannot take a WHERE. DROP removes the table itself including structure and indexes.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 4);
INSERT INTO mock_interview_questions (stack_key, round_number, topic, position, text, category, duration_seconds, note, needs_review, origin, image, created_by, created_at, updated_at)
SELECT 'cs_dbms', 1, 'ACID', 5, 'What are the ACID properties? Explain each with a banking transfer example.', 'technical', 150, 'Atomicity: debit and credit both happen or neither. Consistency: the database moves from one valid state to another, so the total is preserved. Isolation: concurrent transfers do not see each other half-done. Durability: once committed the change survives a crash.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 5);
