SELECT 'cs_dbms', 1, 'SQL clauses', 6, 'Explain the difference between WHERE and HAVING, and between GROUP BY and ORDER BY.', 'technical', 150, 'WHERE filters rows before grouping; HAVING filters groups after aggregation and can use aggregate functions. GROUP BY collapses rows into groups for aggregates; ORDER BY sorts the final result set.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions m WHERE m.stack_key = 'cs_dbms' AND m.round_number = 1 AND m.position = 6);
