SELECT 'cs_dbms', 2, 'Normalization', 1, 'What is normalization? Explain 1NF, 2NF and 3NF with an example of a table that violates each.', 'technical', 150, '1NF: atomic values, no repeating groups. 2NF: 1NF plus no partial dependency of a non-key attribute on part of a composite key. 3NF: 2NF plus no transitive dependency of a non-key attribute on another non-key attribute. Candidate gives a concrete table such as OrderDetails(order_id, product_id, product_name).', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
