SELECT 'cs_dsa', 2, 'Shortest paths', 6, 'Explain Dijkstra\'s algorithm. Why does it fail with negative edge weights, and what do you use instead?', 'technical', 180, 'Greedy: repeatedly settle the unvisited node with the smallest tentative distance (priority queue) and relax its edges; O((V + E) log V). With negative edges a settled node may later be improved, breaking the greedy assumption; use Bellman-Ford (which also detects negative cycles).', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
