SELECT 'cs_dsa', 3, 'Sorting', 1, 'Compare merge sort, quick sort and heap sort: complexity, stability, space and when you would prefer each.', 'technical', 200, 'Merge sort: O(n log n) always, stable, O(n) extra space. Quick sort: average O(n log n), worst O(n squared), in place, not stable, fastest in practice with a good pivot. Heap sort: O(n log n), in place, not stable, poor cache behaviour.', 1, 'generated', NULL, @aptrun_admin, NOW(), NOW()
