-- =====================================================================================================================
-- PART 4 - RECORD THE MIGRATIONS (so `php artisan migrate` on the server will not run them a second time and fail with "already exists")
-- =====================================================================================================================
INSERT INTO migrations (migration, batch)
SELECT m.name, (SELECT COALESCE(MAX(b.batch), 0) + 1 FROM (SELECT batch FROM migrations) b)
  FROM (
    SELECT '2026_11_16_100000_create_generated_reports_table' AS name UNION ALL
    SELECT '2026_11_16_100100_add_schedule_to_interviews_table' UNION ALL
    SELECT '2026_11_16_100200_enable_domain_prep_for_cse'
  ) m
 WHERE NOT EXISTS (SELECT 1 FROM migrations x WHERE x.migration = m.name);

DROP PROCEDURE IF EXISTS _aptrun_add_column;
DROP PROCEDURE IF EXISTS _aptrun_add_index;

-- =====================================================================================================================
-- PART 5 - VERIFY (read-only). Expected on a first run:
--   generated_reports exists ............ 1
--   interviews schedule columns ......... 6
--   cse domain_prep capability .......... 1
--   cse subjects / topics ............... 10 / 51
--   cse questions (published) ........... 160
--   cs_core mock questions .............. 108 (6 stacks, every round >= 5)
--   migrations recorded ................. 3
-- =====================================================================================================================
SELECT 'generated_reports table' AS check_name, COUNT(*) AS n FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'generated_reports'
UNION ALL SELECT 'interviews schedule columns', COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'interviews' AND column_name IN ('opens_at','closes_at','audience_filter','announced_at','open_reminder_sent_at','close_reminder_sent_at')
UNION ALL SELECT 'cse domain_prep capability', COUNT(*) FROM disciplines WHERE code = 'cse' AND JSON_UNQUOTE(JSON_EXTRACT(capabilities, '$.domain_prep')) = 'true'
UNION ALL SELECT 'cse subjects', COUNT(*) FROM core_subjects WHERE discipline_code = 'cse'
UNION ALL SELECT 'cse topics', COUNT(*) FROM core_topics t JOIN core_subjects s ON s.id = t.subject_id WHERE s.discipline_code = 'cse'
UNION ALL SELECT 'cse questions published', COUNT(*) FROM core_questions WHERE discipline_code = 'cse' AND status = 'published'
UNION ALL SELECT 'cs_core mock questions', COUNT(*) FROM mock_interview_questions WHERE stack_key IN ('cs_dbms','cs_os','cs_cn','cs_oop','cs_dsa','cs_se')
UNION ALL SELECT 'migrations recorded', COUNT(*) FROM migrations WHERE migration IN ('2026_11_16_100000_create_generated_reports_table','2026_11_16_100100_add_schedule_to_interviews_table','2026_11_16_100200_enable_domain_prep_for_cse');

